func newInventoryPreloadRecordsApplyCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		fromFile     string
		flagYes      bool
		flagDryRun   bool
		flagScaffold bool
	)

	cmd := &cobra.Command{
		Use:         "apply",
		Short:       "Create or replace a inventory-preload-record by name",
		Annotations: map[string]string{"jamf:api": "pro", "jamf:gateway-privileges": "inventory-preload-records:create,inventory-preload-records:read,inventory-preload-records:update"},
		Long: `Create or replace a inventory-preload-record. Reads JSON or YAML from --from-file or stdin.

The serialNumber field in the input is used to check if the resource
already exists. If it does, the resource is replaced (with confirmation).
If not, a new resource is created.`,
		Example: `  # Apply a inventory-preload-record from a JSON file
  jamf-cli pro inventory-preload-records apply --from-file inventory-preload-record.json

  # Apply a inventory-preload-record from a YAML file
  jamf-cli pro inventory-preload-records apply --from-file inventory-preload-record.yaml

  # Apply from stdin
  cat inventory-preload-record.json | jamf-cli pro inventory-preload-records apply

  # Apply without replacement confirmation
  jamf-cli pro inventory-preload-records apply --from-file inventory-preload-record.json --yes

  # Preview what would happen
  jamf-cli pro inventory-preload-records apply --from-file inventory-preload-record.json --dry-run`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			reqCtx := cmd.Context()
			if flagScaffold {
				return printScaffoldOutput(`{
  "appleCareId": "5678",
  "assetTag": "ABCDEFG12345",
  "barCode1": "123456789",
  "barCode2": "123456789",
  "building": "Eau Claire",
  "department": "IT",
  "deviceType": "Computer",
  "emailAddress": "ITBob@jamf.com",
  "extensionAttributes": [
    {
      "name": "foo",
      "value": "42"
    }
  ],
  "fullName": "Name",
  "leaseExpiration": "2015-06-19",
  "lifeExpectancy": "5 years",
  "phoneNumber": "555-555-5555",
  "poDate": "2019-02-04T21:09:31.661Z",
  "poNumber": "8675309",
  "position": "IT Team Lead",
  "purchasePrice": "$399",
  "purchasingAccount": "IT Budget",
  "purchasingContact": "Nick in IT",
  "room": "4th Floor - Quad 3",
  "serialNumber": "C02L29ECF8J1",
  "username": "admin",
  "vendor": "Apple",
  "warrantyExpiration": "2012-07-21"
}`, ctx.Output.Format())
			}

			// Read input (JSON or YAML). When file flags are present, empty input
			// is OK — the file-field injector constructs a minimal body.
			data, err := readApplyInput(fromFile)
			if err != nil {
				return err
			}
			if len(data) > 0 {
				data, err = normalizeInputToJSON(data)
				if err != nil {
					return err
				}
			}

			// Extract name from JSON input
			name, err := extractJSONField(data, "serialNumber")
			if err != nil {
				return fmt.Errorf("input must include a %q field: %w", "serialNumber", err)
			}

			// Check if resource exists by name (read-only, runs even in dry-run)
			noInput, _ := cmd.Flags().GetBool("no-input")
			id, err := resolveNameToIDForApply(reqCtx, ctx.Client, "/v2/inventory-preload/records", "serialNumber", "id", name, noInput)
			if err != nil {
				return err
			}

			if id == "" {
				// Not found — create
				if flagDryRun {
					fmt.Fprintf(os.Stderr, "[dry-run] Would create inventory-preload-record %q\n", name)
					return nil
				}
				resp, err := ctx.Client.Do(reqCtx, "POST", "/v2/inventory-preload/records", bytes.NewReader(data))
				if err != nil {
					return err
				}
				defer resp.Body.Close()
				fmt.Fprintf(os.Stderr, "Created inventory-preload-record %q\n", name)
				return ctx.Output.PrintResponse(resp)
			}

			// Found — replace
			if flagDryRun {
				fmt.Fprintf(os.Stderr, "[dry-run] Would replace inventory-preload-record %q (id: %s)\n", name, id)
				return nil
			}
			if !flagYes {
				if noInput {
					return fmt.Errorf("inventory-preload-record %q already exists (id: %s); use --yes to replace when --no-input is set", name, id)
				}
				fmt.Fprintf(os.Stderr, "inventory-preload-record %q already exists (id: %s) and will be replaced. Type 'yes' to confirm: ", name, id)
				var confirm string
				fmt.Scanln(&confirm)
				if confirm != "yes" {
					return fmt.Errorf("aborted")
				}
			}

			updatePath := strings.Replace("/v2/inventory-preload/records/{id}", "{id}", url.PathEscape(id), 1)
			resp, err := ctx.Client.Do(reqCtx, "PUT", updatePath, bytes.NewReader(data))
			if err != nil {
				return err
			}
			defer resp.Body.Close()
			fmt.Fprintf(os.Stderr, "Replaced inventory-preload-record %q (id: %s)\n", name, id)
			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().StringVar(&fromFile, "from-file", "", "Path to JSON or YAML input file (or pipe to stdin)")
	cmd.Flags().BoolVar(&flagYes, "yes", false, "Skip confirmation prompt when replacing")
	cmd.Flags().BoolVarP(&flagDryRun, "dry-run", "n", false, "Preview without executing")
	cmd.Flags().BoolVar(&flagScaffold, "scaffold", false, "Print a JSON template for the request body and exit")

	return cmd
}
